import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"豐","description":"周易集解 - 豐","frontmatter":{"title":"豐","description":"周易集解 - 豐"},"headers":[],"relativePath":"zh/classics/jijie/055.md","filePath":"zh/classics/jijie/055.md"}'),l={name:"zh/classics/jijie/055.md"};function p(n,a,d,t,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="豐" tabindex="-1">豐 <a class="header-anchor" href="#豐" aria-label="Permalink to “豐”">​</a></h1><h2 id="豐-1" tabindex="-1">豐 <a class="header-anchor" href="#豐-1" aria-label="Permalink to “豐”">​</a></h2><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>豐，亨，王假之，勿憂，宜日中。</p><h2 id="卦辞注" tabindex="-1">卦辞注 <a class="header-anchor" href="#卦辞注" aria-label="Permalink to “卦辞注”">​</a></h2><p>《序卦》曰：得其所歸者必大，故受之以豐。豐者，大也。</p><p>崔憬曰：歸妹者，姪娣媵。國三人，凡九女，為大援。故言得其所歸者必大也。</p><p>虞翻曰：此卦三陰三陽之例，當從泰二之四。而豐三從噬嗑上來之三，折四於五獄中而成豐，故君子以折獄致刑。陰陽交，故通。噬嗑所謂利用獄者，此卦之謂也。</p><p>虞翻曰：乾為王。假，至也。謂四宜上至五，動之正成乾，故｢王假之，尚大也｣。</p><p>虞翻曰：五動之正，則四變成離。離日中，當五在坎中，坎為憂。故｢勿憂，宜日中｣。體兩離象，照天下也。日中則昃，月盈則蝕，天地盈虛，與時消息。</p><p>乾寶曰：豐坎宮，陰世在五。以其宜中，而憂其側也。坎為夜，離為晝，以離變坎，至於天位，日中之象也。殷水德坎象，晝敗而離居之，周伐殷，居王位之象也。聖人德大而心小，既居天位，而戒懼不怠。勿憂者，勸勉之言也。猶《詩》曰：上帝臨汝，無貳爾心。言周德當天人之心，宜居王位，故宜日中。</p><h2 id="彖" tabindex="-1">彖 <a class="header-anchor" href="#彖" aria-label="Permalink to “彖”">​</a></h2><p>《彖》曰：豐，大也。明以動，故豐。王假之，尚大也。勿憂，宜日中，</p><h2 id="彖传注" tabindex="-1">彖传注 <a class="header-anchor" href="#彖传注" aria-label="Permalink to “彖传注”">​</a></h2><p>崔憬曰：離下震上，明以動之。象明則見微，動則成務，故能大矣。</p><p>姚信曰：四體震。王假，大也。四上之五，得其盛位，謂之大。</p><p>《九家易》曰：震動而上，故勿憂也。日者君。中者五。君宜居五也。謂陰處五，日中之位，當傾昃矣。</p><p>虞翻曰：五動成乾，乾為天。四動成兩離，重明麗正，故宜照天下。謂化成天下也。</p><p>荀爽曰：豐者至盛，故曰中。下居四，日昃之象也。</p><p>虞翻曰：月之行，生震見兌，盈於乾甲，五動成乾，故月盈。四變體噬嗑食，故則食。此豐其屋，蔀其家也。</p><p>虞翻曰：五息成乾，為盈；四消入坤，為虛，故天地盈虛也。豐之既濟，四時象具。乾為神人，坤為鬼，鬼神與人，亦隨時消息。謂人謀鬼謀，百姓與能，與時消息。</p><h2 id="象" tabindex="-1">象 <a class="header-anchor" href="#象" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：雷電皆至，豐。君子以折獄致刑。</p><h2 id="象传注" tabindex="-1">象传注 <a class="header-anchor" href="#象传注" aria-label="Permalink to “象传注”">​</a></h2><p>荀爽曰：豐者，陰據不正，奪陽之位而行以豐。故折獄致刑，以討除之也。</p><p>虞翻曰：君子謂三。噬嗑四失正，繫在坎獄中，故上之三。折四入大過，死象。故以折獄致刑。兌折為刑，賁三得正，故無敢折獄也。</p><h2 id="初九" tabindex="-1">初九 <a class="header-anchor" href="#初九" aria-label="Permalink to “初九”">​</a></h2><p>初九，遇其配主，雖旬無咎，往有尚。</p><h2 id="初九注" tabindex="-1">初九注 <a class="header-anchor" href="#初九注" aria-label="Permalink to “初九注”">​</a></h2><p>虞翻曰：妃嬪，謂四也。四失位在震，為主；五動體姤遇，故遇其配主也。</p><p>虞翻曰：謂四失位，變成坤，應初。坤數十，四上之五，成離。離為日。</p><h2 id="象-1" tabindex="-1">象 <a class="header-anchor" href="#象-1" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：雖旬無咎，過旬災也。</p><h2 id="象传注-1" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-1" aria-label="Permalink to “象传注”">​</a></h2><p>虞翻曰：體大過，故過旬災。四上之五，坎為災也。</p><h2 id="六二" tabindex="-1">六二 <a class="header-anchor" href="#六二" aria-label="Permalink to “六二”">​</a></h2><p>六二，豐其蔀，日中見鬥，往得疑疾。有孚發若，吉。</p><h2 id="六二注" tabindex="-1">六二注 <a class="header-anchor" href="#六二注" aria-label="Permalink to “六二注”">​</a></h2><p>虞翻曰：日蔽雲中，稱蔀。蔀，小，謂四也。二利四之五，故豐其蔀。噬嗑離為見，象在上，為日中。艮為鬥。鬥，七星也。噬嗑艮為星，為止，坎為北中，巽為高舞。星上於中而舞者，北斗之象也。離上之三，隱坎雲下，故日中見鬥。四往之五，得正成坎，坎為疑疾，故往得疑疾也。</p><p>虞翻曰：坎為孚，四發之五成坎孚，動而得位，故有孚發若吉也。</p><h2 id="象-2" tabindex="-1">象 <a class="header-anchor" href="#象-2" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：有孚發若，信以發志也。</p><h2 id="象传注-2" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-2" aria-label="Permalink to “象传注”">​</a></h2><p>虞翻曰：四發之五，坎為志也。</p><p>《九家易》曰：信著於五，然後乃可發其順志。</p><h2 id="九三" tabindex="-1">九三 <a class="header-anchor" href="#九三" aria-label="Permalink to “九三”">​</a></h2><p>九三，豐其沛，日中見沬，折其右肱，無咎。</p><h2 id="九三注" tabindex="-1">九三注 <a class="header-anchor" href="#九三注" aria-label="Permalink to “九三注”">​</a></h2><p>虞翻曰：日在雲下稱沛。沛，不明也。沬，小星也。噬嗑離為日，艮為沬。故日中見沬。上之三，日入坎雲下，故見沬也。</p><p>《九家易》曰：大暗謂之沛。沬，鬥杓後小星也。</p><p>虞翻曰：兌為折，為右。噬嗑艮為肱。上來之三，折艮入兌，故折其右肱。之三得正，故無咎也。</p><h2 id="象-3" tabindex="-1">象 <a class="header-anchor" href="#象-3" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：豐其沛，不可大事也。折其右肱，終不可用也。</p><h2 id="象传注-3" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-3" aria-label="Permalink to “象传注”">​</a></h2><p>虞翻曰：利四之陰，故不可大事。</p><p>虞翻曰：四死大過，故終不可用。</p><h2 id="九四" tabindex="-1">九四 <a class="header-anchor" href="#九四" aria-label="Permalink to “九四”">​</a></h2><p>九四，豐其蔀，日中見鬥，遇其夷主，吉。</p><h2 id="九四注" tabindex="-1">九四注 <a class="header-anchor" href="#九四注" aria-label="Permalink to “九四注”">​</a></h2><p>虞翻曰：蔀，蔽也。噬嗑離日之坎雲中，故豐其蔀。《象》曰｢位不當也｣。</p><p>虞翻曰：噬嗑日在上，為中。上之三為巽，巽為入。日入坎雲下，幽伏不明，故日中見鬥。《象》曰｢幽不明｣，是其義也。</p><p>虞翻曰：震為主。四行之正成明夷，則三體震，為夷主，故遇其夷主吉也。</p><p>按：四處上卦之下，以陽居陰，履非其位，而比於五故曰遇也。夷者，傷也。主者，五也。謂四不期相遇，而能上行傷五，則吉。故曰｢遇其夷主，吉行也｣。</p><h2 id="象-4" tabindex="-1">象 <a class="header-anchor" href="#象-4" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：豐其蔀，位不當也。日中見鬥，幽不明也。遇其夷主，吉行也。</p><h2 id="象传注-4" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-4" aria-label="Permalink to “象传注”">​</a></h2><p>虞翻曰：離上變入坎雲下，故幽不明。坎，幽也。</p><p>虞翻曰：動體明夷。震為行，故曰吉行。</p><h2 id="六五" tabindex="-1">六五 <a class="header-anchor" href="#六五" aria-label="Permalink to “六五”">​</a></h2><p>六五，來章，有慶譽，吉。</p><h2 id="六五注" tabindex="-1">六五注 <a class="header-anchor" href="#六五注" aria-label="Permalink to “六五注”">​</a></h2><p>虞翻曰：在內稱來。章，顯也。慶謂五。陽出稱慶也。譽謂二，二多譽。五發得正，則來應二。故｢來章，有慶譽，吉｣也。</p><h2 id="象-5" tabindex="-1">象 <a class="header-anchor" href="#象-5" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：六五之吉，有慶也。</p><h2 id="象传注-5" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-5" aria-label="Permalink to “象传注”">​</a></h2><p>虞翻曰：動而成乾，乾為慶。</p><h2 id="上六" tabindex="-1">上六 <a class="header-anchor" href="#上六" aria-label="Permalink to “上六”">​</a></h2><p>上六，豐其屋，蔀其家。闚其戶，闃其無人。三歲不覿，凶。</p><h2 id="上六注" tabindex="-1">上六注 <a class="header-anchor" href="#上六注" aria-label="Permalink to “上六注”">​</a></h2><p>虞翻曰：豐，大。蔀，小也。三至上，體大壯，屋象，故豐其屋。謂四五已變，上動成家人。大屋見則家人懷，故蔀其家。與泰二同義。故《象》曰：天際祥明，以大壯為屋象故也。</p><p>虞翻曰：謂從外闚三應。闃，空也。四動時坤為闔戶。闔，故闚其戶。坤為空虛，三隱伏坎中，故闃其無人。《象》曰｢自藏也｣。四五易位，噬嗑離目，為闚。闚人者，言皆不見。坎為三歲，坤冥在上，離象不見。故｢三歲不覿，凶｣。</p><p>乾寶曰：在豐之家，居乾之位，乾為屋宇，故曰豐其屋。此蓋記紂之侈，造為璿室玉台也。蔀其家者，以記紂多傾國之女也。社稷既亡，宮室虛曠，故曰｢闚其戶，闃其無人｣。闃，無人貌也。三者，天地人之數也。凡國於天地有興亡焉。故王者之亡其家也。必天示其祥，地出其妖，人反其常，非斯三者，亦弗之亡也。故曰｢三歲不覿，凶｣。然則璿室之成，三年而後亡國矣。</p><p>案：上應於三，三互離，巽為戶，離為目，目而近戶，闚之象也。既屋豐家蔀，若闚地戶，闃寂無人。震木，數三，故三歲致凶於災。</p><h2 id="象-6" tabindex="-1">象 <a class="header-anchor" href="#象-6" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：豐其屋，天降祥也。闚其戶，闃其無人，自藏也。</p><h2 id="象传注-6" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-6" aria-label="Permalink to “象传注”">​</a></h2><p>孟喜曰：天降下惡祥也。</p><p>闚其戶，闃其無人，自藏也。</p><p>虞翻曰：謂三隱伏坎中，故自藏者也。</p>',89)])])}const m=e(l,[["render",p]]);export{b as __pageData,m as default};
